const searchResult = $input.first().json;
const ctx = $('Контекст').first().json;

// Извлекаем текст документации из ответа MCP
let nodesDocs = '';
try {
  const content = searchResult?.result?.content;
  if (Array.isArray(content)) {
    nodesDocs = content.map(c => c.text || '').join('\n');
  } else if (typeof content === 'string') {
    nodesDocs = content;
  }
} catch(e) {
  nodesDocs = 'Документация нод недоступна';
}

return [{
  json: {
    ...ctx,
    nodesDocs: nodesDocs.substring(0, 8000) // ограничиваем размер
  }
}];

const items = $input.all();
const ctx = $('Парсинг результатов').first().json;

let allDocs = ctx.searchSummary + '\n\n';

for (const item of items) {
  const data = item.json;
  const content = data?.result?.content;
  let text = '';

  if (Array.isArray(content)) {
    text = content.map(c => c.text || '').join('\n');
  } else if (typeof content === 'string') {
    text = content;
  }

  if (text) {
    allDocs += text.substring(0, 2000) + '\n\n';
  }
}

return [{
  json: {
    businessTask: ctx.businessTask,
    failedTemplates: ctx.failedTemplates || '[]',
    exampleWorkflow: ctx.exampleWorkflow,
    rules: ctx.rules,
    nodesDocs: allDocs.substring(0, 10000)
  }
}];

