const rules = [
  'ОБЯЗАТЕЛЬНЫЕ ПРАВИЛА:',
  '',
  '[ОБЪЁМ ЗАДАЧИ]',
  '- Реализуй ТОЛЬКО то что явно указано в задаче — никаких дополнительных фич по своей инициативе',
