const response = $input.first().json;

console.log('Full Claude response:', JSON.stringify(response).substring(0, 500));

if (response.error) {
  return [{ json: { 
    text: '', 
    error: response.error, 
    businessTask: $('Execute Sub-workflow Trigger').first().json.businessTask 
  }}];
}

// Claude возвращает content как массив блоков разных типов
// tool_use блоки = вызовы MCP (нас не интересуют)
// text блоки = финальный ответ (нас интересует)
const content = response.content || [];
const textBlock = content.find(b => b.type === 'text');
let text = textBlock?.text || '';

if (!text || text.trim() === '') {
  return [{ json: { 
    text: '', 
    error: { message: 'Claude вернул пустой ответ. stop_reason: ' + response.stop_reason }, 
    businessTask: $('Execute Sub-workflow Trigger').first().json.businessTask 
  }}];
}

// Claude иногда оборачивает в markdown блок — убираем
text = text.replace(/^```json\s*/i, '').replace(/\s*```$/, '').trim();

// Проверяем что это JSON и что нод достаточно
try {
  const parsed = JSON.parse(text);
  if ((parsed.nodes?.length || 0) <= 1) {
    return [{ json: { 
      text: '', 
      error: { message: 'Воркфлоу содержит только ' + (parsed.nodes?.length || 0) + ' ноду — слишком мало' }, 
      businessTask: $('Execute Sub-workflow Trigger').first().json.businessTask 
    }}];
  }
} catch(e) {
  // не парсится — пускаем дальше, валидация разберётся
}

return [{
  json: {
    text: text,
    businessTask: $('Execute Sub-workflow Trigger').first().json.businessTask
  }
}];

const raw = $input.first().json;
const ctx = $('Парсинг API search1').first().json;

// Парсим ответ от MCP: Get API Docs
let mcpData = null;
const rawText = typeof raw === 'string' ? raw : (raw.data || raw.body || JSON.stringify(raw));

if (typeof raw === 'object' && raw.result) {
  mcpData = raw;
} else {
  const lines = String(rawText).split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('data: ')) {
      try { mcpData = JSON.parse(trimmed.substring(6)); break; } catch(e) {}
    }
  }
  if (!mcpData) {
    try { mcpData = JSON.parse(String(rawText)); } catch(e) {}
  }
}

let apiDocsText = '';
if (mcpData?.result?.content) {
  const content = mcpData.result.content;
  if (Array.isArray(content)) apiDocsText = content.map(c => c.text || '').join('\n');
  else if (typeof content === 'string') apiDocsText = content;
}

