// Алиасы
const aliases = {
  'nano-banana': 'gemini', 'nanbanana': 'gemini', 'imagen': 'gemini',
  'gpt': 'openai', 'chatgpt': 'openai', 'dall-e': 'openai', 'dalle': 'openai',
  'вк': 'vk', 'вконтакте': 'vk', 'vkontakte': 'vk',
  'тг': 'telegram', 'tg': 'telegram', 'тelegram': 'telegram',
};

// Для каждого сервиса — проверяем есть ли он в MCP, если нет — добавляем из knownApis
const allServices = ctx.apiSearchQueriesAll || [];
const extraDocs = [];
const mcpLower = apiDocsText.toLowerCase();

for (let service of allServices) {
  service = service.toLowerCase();
  const resolvedKey = aliases[service] || service;
  const isCoveredByMcp = mcpLower.includes(service) || mcpLower.includes(resolvedKey);
  if (!isCoveredByMcp && knownApis[resolvedKey]) {
    extraDocs.push(`# [Fallback] ${resolvedKey}\n` + knownApis[resolvedKey]);
  }
}

const combinedApiDocs = [apiDocsText, ...extraDocs]
  .filter(Boolean)
  .join('\n\n---\n\n')
  .substring(0, 18000);

return [{
  json: {
    businessTask: ctx.businessTask,
    failedTemplates: ctx.failedTemplates,
    exampleWorkflow: ctx.exampleWorkflow,
    apiPatterns: ctx.apiPatterns,
    rules: ctx.rules,
    nodesDocs: ctx.nodesDocs,
    apiDocs: combinedApiDocs
  }
}];

