        type: "n8n-nodes-base.code", typeVersion: 2,
        position: [470, 300],
        parameters: {
          mode: "runOnceForEachItem",
          jsCode: "const cfg = {\n  TG_BOT_TOKEN: 'PASTE_TOKEN',\n  ALLOWED_CHAT_IDS: [],\n  TG_CHANNEL_CHAT_ID: '@channel',\n  VK_GROUP_ID: '123',\n  VK_USER_ID: '456',\n  VK_GROUP_TOKEN: 'PASTE',\n  VK_USER_TOKEN: 'PASTE',\n  VK_API_VERSION: '5.199'\n};\nconst staticData = $getWorkflowStaticData('global');\nconst msg = $json.message || {};\nconst chatId = msg.chat?.id;\nconst text = (msg.text || '').trim();\nconst lower = text.toLowerCase();\nif (!chatId) return [{ json: { action: 'ignore', chatId: 0, cfg } }];\nif (cfg.ALLOWED_CHAT_IDS.length && !cfg.ALLOWED_CHAT_IDS.includes(chatId)) return [{ json: { action: 'unauthorized', chatId, cfg } }];\nconst stateKey = 's_' + chatId;\nconst state = staticData[stateKey] || {};\nlet action = 'unsupported';\nif (lower === 'отмена' || lower === '/cancel') {\n  delete staticData[stateKey];\n  return [{ json: { action: 'cancelled', chatId, cfg } }];\n}\nif (lower === 'выложи пост') {\n  staticData[stateKey] = { awaiting: 'post_text' };\n  action = 'ask_post';\n} else if (state.awaiting === 'post_text' && text) {\n  delete staticData[stateKey];\n  action = 'process_post';\n}\nreturn [{ json: { action, chatId, text, cfg } }];"
