        type: "n8n-nodes-base.switch", typeVersion: 3.2,
        position: [690, 300],
        parameters: {
          mode: "expression",
          numberOutputs: 4,
          output: "={{ ({ ask_post: 0, process_post: 1, unauthorized: 2 })[$json.action] ?? 3 }}"
        }
      },
      {
        id: "http-ask", name: "Reply Ask Post",
        type: "n8n-nodes-base.httpRequest", typeVersion: 4.2,
        position: [910, 200],
        parameters: {
          method: "POST",
          url: "=https://api.telegram.org/bot{{ $json.cfg.TG_BOT_TOKEN }}/sendMessage",
          sendBody: true, specifyBody: "json",
          jsonBody: "={{ JSON.stringify({ chat_id: $json.chatId, text: 'Отправьте текст поста:' }) }}",
