        parameters: {
          color: 3, width: 700, height: 400,
          content: "## Telegram Bot\n\n### Credentials\n- TG_BOT_TOKEN: токен от @BotFather\n\n### Важно\n- Router + Config использует $getWorkflowStaticData для двухшагового диалога\n- Switch роутит по полю action, НЕ по тексту сообщения\n- После каждого HTTP Request — Code нода для восстановления контекста\n- Публикация последовательная: TG → VK Group → VK User → Notify"
        }
      }
    ],
    connections: {
      "Telegram Trigger": { main: [[{ node: "Router + Config", type: "main", index: 0 }]] },
      "Router + Config": { main: [[{ node: "Action Switch", type: "main", index: 0 }]] },
      "Action Switch": { main: [
        [{ node: "Reply Ask Post", type: "main", index: 0 }],
        [{ node: "Publish To Channel", type: "main", index: 0 }],
        [{ node: "Notify Done", type: "main", index: 0 }],
        [{ node: "Notify Done", type: "main", index: 0 }]
      ]},
      "Publish To Channel": { main: [[{ node: "Restore After Publish", type: "main", index: 0 }]] },
      "Restore After Publish": { main: [[{ node: "Notify Done", type: "main", index: 0 }]] }
    },
    settings: { executionOrder: "v1" }
  };
} else if (task.includes('schedule') || task.includes('расписани') || task.includes('каждый') || task.includes('cron') || task.includes('автомат')) {
  example = {
    name: "Scheduled API Task",
    nodes: [
      { id: "sched-1", name: "Schedule Trigger", type: "n8n-nodes-base.scheduleTrigger", typeVersion: 1.2,
        position: [250, 300], parameters: { rule: { interval: [{ field: "hours", hoursInterval: 1 }] } } },
      { id: "http-1", name: "Fetch Data", type: "n8n-nodes-base.httpRequest", typeVersion: 4.2,
        position: [470, 300], parameters: { method: "GET", url: "https://api.example.com/data", options: { timeout: 30000, response: { response: { neverError: true, responseFormat: "json" } } } } },
      { id: "code-1", name: "Process Data", type: "n8n-nodes-base.code", typeVersion: 2,
        position: [690, 300], parameters: { jsCode: "const data = $input.first().json;\nreturn [{ json: { processed: data, timestamp: new Date().toISOString() } }];" } },
      { id: "http-2", name: "Send Notification", type: "n8n-nodes-base.httpRequest", typeVersion: 4.2,
        position: [910, 300], parameters: { method: "POST", url: "=https://api.telegram.org/bot{{$env.BOT_TOKEN}}/sendMessage", sendBody: true, specifyBody: "json", jsonBody: "={{ JSON.stringify({ chat_id: $env.CHAT_ID, text: 'Обновление: ' + JSON.stringify($json.processed).substring(0, 500) }) }}", options: { timeout: 30000, response: { response: { neverError: true, responseFormat: "json" } } } } },
      { id: "sticky-1", name: "Инструкция", type: "n8n-nodes-base.stickyNote", typeVersion: 1,
        position: [240, -200], parameters: { color: 3, width: 600, height: 350, content: "## Scheduled Task\n\n### Credentials\n- BOT_TOKEN: токен Telegram\n- CHAT_ID: ID чата для уведомлений\n\n### Настройка\n- Изменить интервал в Schedule Trigger\n- Указать endpoint в Fetch Data" } }
    ],
    connections: {
      "Schedule Trigger": { main: [[{ node: "Fetch Data", type: "main", index: 0 }]] },
      "Fetch Data": { main: [[{ node: "Process Data", type: "main", index: 0 }]] },
      "Process Data": { main: [[{ node: "Send Notification", type: "main", index: 0 }]] }
    },
    settings: { executionOrder: "v1" }
  };
} else if (task.includes('webhook') || task.includes('form') || task.includes('форм') || task.includes('заявк')) {
  example = {
    name: "Webhook to Google Sheets",
    nodes: [
      { id: "wh-1", name: "Webhook", type: "n8n-nodes-base.webhook", typeVersion: 2,
        position: [250, 300], parameters: { httpMethod: "POST", path: "my-hook", responseMode: "lastNode", options: {} } },
      { id: "set-1", name: "Prepare Data", type: "n8n-nodes-base.set", typeVersion: 3.4,
        position: [450, 300], parameters: { mode: "manual", assignments: { assignments: [
          { id: "f1", name: "name", value: "={{ $json.body.name }}", type: "string" },
          { id: "f2", name: "email", value: "={{ $json.body.email }}", type: "string" }
        ] }, options: {} } },
      { id: "gs-1", name: "Google Sheets", type: "n8n-nodes-base.googleSheets", typeVersion: 4.5,
        position: [650, 300], parameters: { operation: "appendOrUpdate", documentId: { __rl: true, mode: "id", value: "" }, sheetName: { __rl: true, mode: "name", value: "Sheet1" }, columns: { mappingMode: "autoMapInputData" }, options: {} } },
      { id: "sticky-1", name: "Инструкция", type: "n8n-nodes-base.stickyNote", typeVersion: 1,
        position: [240, -300], parameters: { color: 3, width: 700, height: 500, content: "## Webhook → Sheets\n\n### Credentials\n- Google Sheets: подключить OAuth2\n\n### Настройка\n- Указать documentId таблицы\n- Первая строка = заголовки: name, email" } }
    ],
    connections: {
      "Webhook": { main: [[{ node: "Prepare Data", type: "main", index: 0 }]] },
      "Prepare Data": { main: [[{ node: "Google Sheets", type: "main", index: 0 }]] }
    },
    settings: { executionOrder: "v1" }
  };
} else {
  example = {
    name: "HTTP API Integration",
    nodes: [
      { id: "wh-1", name: "Webhook", type: "n8n-nodes-base.webhook", typeVersion: 2,
        position: [250, 300], parameters: { httpMethod: "POST", path: "trigger", responseMode: "lastNode", options: {} } },
      { id: "code-1", name: "Prepare Request", type: "n8n-nodes-base.code", typeVersion: 2,
        position: [470, 300], parameters: { jsCode: "const input = $input.first().json;\nreturn [{ json: { payload: input.body, timestamp: new Date().toISOString() } }];" } },
      { id: "http-1", name: "Call API", type: "n8n-nodes-base.httpRequest", typeVersion: 4.2,
        position: [690, 300], parameters: { method: "POST", url: "https://api.example.com/endpoint", authentication: "genericCredentialType", genericAuthType: "httpBearerAuth", sendBody: true, specifyBody: "json", jsonBody: "={{ JSON.stringify({ data: $json.payload }) }}", options: { timeout: 30000, response: { response: { neverError: true, responseFormat: "json" } } } } },
      { id: "code-2", name: "Restore Context", type: "n8n-nodes-base.code", typeVersion: 2,
        position: [910, 300], parameters: { jsCode: "const response = $input.first().json;\nconst ctx = $('Prepare Request').first().json;\nreturn [{ json: { ...ctx, result: response } }];" } },
      { id: "sticky-1", name: "Инструкция", type: "n8n-nodes-base.stickyNote", typeVersion: 1,
        position: [240, -200], parameters: { color: 3, width: 600, height: 400, content: "## API Integration\n\n### Credentials\n- Bearer token в credentials\n\n### Важно\n- После каждого HTTP Request — Code нода для восстановления контекста" } }
    ],
    connections: {
      "Webhook": { main: [[{ node: "Prepare Request", type: "main", index: 0 }]] },
      "Prepare Request": { main: [[{ node: "Call API", type: "main", index: 0 }]] },
      "Call API": { main: [[{ node: "Restore Context", type: "main", index: 0 }]] }
    },
    settings: { executionOrder: "v1" }
  };
}

// ═══════════════════════════════════════════════════════════════
// ПАТТЕРНЫ ИНТЕГРАЦИЙ
// ═══════════════════════════════════════════════════════════════

const apiPatterns = [
  '=== ПАТТЕРНЫ ИНТЕГРАЦИЙ (КРИТИЧНО — следуй этим правилам!) ===',
  '',
  '[TELEGRAM BOT — ДВУХШАГОВЫЙ ДИАЛОГ (САМОЕ ВАЖНОЕ)]',
  '- Если бот ждёт ответ от пользователя (текст, фото, видео) после команды — ОБЯЗАТЕЛЬНО используй $getWorkflowStaticData("global")',
  '- Паттерн: ОДНА нода "Router + Config" (type: code) содержит:',
  '  1) Объект cfg со всеми настройками (токены, ID)',
  '  2) const staticData = $getWorkflowStaticData("global");',
  '  3) const state = staticData["s_" + chatId] || {};',
  '  4) Логика: если команда → записать ожидание: staticData["s_"+chatId] = { awaiting: "тип" };',
  '  5) Если state.awaiting совпадает и есть данные → delete staticData["s_"+chatId]; action = "process_xxx";',
  '  6) return [{ json: { action, chatId, text, cfg, ...доп.данные } }];',
  '- За Router ВСЕГДА идёт Switch нода с mode:"expression" которая роутит по $json.action',
  '- Switch output mapping: { ask_post: 0, ask_story: 1, process_post: 2, process_story: 3, unauthorized: 4, cancelled: 5 }[$json.action] ?? 6',
  '- НИКОГДА не роуть по содержимому сообщения в Switch — только по action из Router',
  '- ВСЕГДА обрабатывай команду отмены: "отмена" и "/cancel" → delete staticData[stateKey]',
  '- ВСЕГДА проверяй ALLOWED_CHAT_IDS для авторизации',
  '- ВСЕГДА добавляй ответ "Неизвестная команда" для unsupported action',
  '',
  '[TELEGRAM BOT — МЕДИА (ФОТО/ВИДЕО)]',
  '- Фото: msg.photo — массив, бери последний элемент (лучшее качество): msg.photo[msg.photo.length-1].file_id',
  '- Видео: msg.video.file_id',
  '- Документ: msg.document.file_id',
  '- Определяй mediaType: photo/video/document для выбора правильного VK метода',
  '- В state.awaiting для сторис проверяй наличие медиа, а не текста',
  '',
  '[ПАРАЛЛЕЛЬНЫЕ ВЕТКИ — ЗАПРЕЩЕНО ДЛЯ УВЕДОМЛЕНИЙ]',
  '- Если после параллельных веток стоит ОДНА общая нода (например Notify Done) — она сработает ДВАЖДЫ',
  '- ПРАВИЛО: если результат всех веток сходится в одно уведомление — делай ПОСЛЕДОВАТЕЛЬНУЮ цепочку:',
  '  Правильно: API_1 → Restore → API_2 → Restore → API_3 → Restore → Notify',
  '  Неправильно: Restore → [API_1, API_2] → Notify (Notify сработает 2 раза)',
  '- Параллельные ветки допустимы ТОЛЬКО если у каждой своя конечная нода',
  '- Для публикации в несколько соцсетей: TG Channel → Restore → VK Group → Restore → VK User → Restore → Notify (ПОСЛЕДОВАТЕЛЬНО)',
  '',
  '[MERGE ПОСЛЕ IF/SWITCH — ПРАВИЛЬНЫЙ ПАТТЕРН]',
  '- Когда две ветки (например AI и No AI) должны сойтись в одну — НЕ используй try/catch с $("Node").first()',
  '- $("NodeName").first() ВЫБРОСИТ ОШИБКУ если нода не выполнялась в текущем запуске',
  '- ПРАВИЛЬНО: обе ветки подключай напрямую к следующей ноде через connections:',
  '  "Branch A": { main: [[{ node: "Next Step" }]] },',
  '  "Branch B": { main: [[{ node: "Next Step" }]] }',
  '- n8n автоматически возьмёт данные из той ветки которая сработала',
  '- НЕ НУЖНА отдельная Merge нода — просто два connection к одной целевой ноде',
  '- ЗАПРЕЩЕНО: try { ctx = $("A").first().json } catch { ctx = $("B").first().json }',
  '',
  '[BINARY FILES В N8N — КРИТИЧНО]',
  '- После скачивания файла (responseFormat: "file") данные попадают в item.binary',
  '- Для передачи binary через Code ноду ОБЯЗАТЕЛЬНО:',
  '  const item = $input.first();',
  '  const ctx = $("ИмяНоды").first().json;',
  '  return [{ json: { ...ctx }, binary: item.binary }];',
  '- При upload (multipart-form-data): parameterType: "formBinaryData", inputDataFieldName: "data"',
  '- НЕЛЬЗЯ делать параллельные ветки с одним binary — данные потеряются',
  '- Делай ПОСЛЕДОВАТЕЛЬНО: скачать → upload group → получить URL user → upload user',
  '- Для повторного upload того же файла: бери binary из ноды где скачивал: $("Download").first().binary',
  '',
  '[VK API — КРИТИЧНО]',
  '- VK принимает запросы через GET с query params, НЕ через POST+JSON body',
  '- Для публикации в группе: owner_id = "-" + GROUP_ID (строка с минусом)',
  '- Для публикации на личной странице: owner_id = USER_ID (положительное число)',
  '- VK использует ДВА РАЗНЫХ токена:',
  '  * VK_GROUP_TOKEN — для публикации от имени группы (wall.post с from_group=1, stories в группу)',
  '  * VK_USER_TOKEN — для публикации на личной стене и в личные сторис',
  '- Для сторис группы: stories.getPhotoUploadServer с group_id (без минуса) + VK_GROUP_TOKEN',
  '- Для сторис личной: stories.getPhotoUploadServer без group_id + VK_USER_TOKEN',
  '- Для видео-сторис: stories.getVideoUploadServer вместо getPhotoUploadServer',
  '- Загрузка медиа всегда 2 шага: 1) GET upload_url 2) POST multipart/form-data на upload_url',
  '',
  '[RESTORE CONTEXT — ОБЯЗАТЕЛЬНО после каждого HTTP Request]',
  '- HTTP Request затирает контекст предыдущих нод. ВСЕГДА добавляй Code ноду после HTTP Request:',
  '  const response = $input.first().json;',
  '  const ctx = $("ИмяПредыдущейНоды").first().json;',
  '  return [{ json: { ...ctx, apiResult: response } }];',
  '- Если HTTP Request скачивал файл (binary), восстанавливай и binary:',
  '  const item = $input.first();',
  '  const ctx = $("ИмяНоды").first().json;',
  '  return [{ json: { ...ctx }, binary: item.binary }];',
  '',
  '[OPENAI GPT]',
  '- POST https://api.openai.com/v1/chat/completions',
  '- Авторизация: sendHeaders с Authorization: Bearer KEY',
  '- Ответ: response.choices[0].message.content',
  '- Для JSON-ответа: добавь в system prompt "Верни ТОЛЬКО JSON" + try/catch при парсинге с fallback',
  '',
  '[TELEGRAM — ОТПРАВКА СООБЩЕНИЙ]',
  '- POST https://api.telegram.org/bot{TOKEN}/sendMessage',
  '- Body: { chat_id, text, parse_mode: "HTML" (опционально) }',
  '- Токен в URL, НЕ в заголовке',
  '- Лимит: 4096 символов для текста',
  '- Для получения файла: GET .../getFile?file_id=XXX → result.file_path',
  '- Скачать: GET https://api.telegram.org/file/bot{TOKEN}/{file_path}',
  '',
  '[ЗАПРЕЩЕНО В CODE НОДАХ]',
  '- process.env — используй $env.ИМЯ или cfg объект',
  '- require() — не работает в n8n Code нодах',
  '- Глобальные переменные между нодами — используй $getWorkflowStaticData или передавай через json',
].join('\n');

// ═══════════════════════════════════════════════════════════════
// ПРАВИЛА ГЕНЕРАЦИИ
// ═══════════════════════════════════════════════════════════════

const rules = [
  'ПРАВИЛА ГЕНЕРАЦИИ:',
  '',
  '[SCOPE] Реализуй ТОЛЬКО то что указано в задаче. Никаких дополнительных фич.',
  '[SCOPE] Простейшая архитектура — меньше нод лучше чем больше.',
  '',
  '[СТРУКТУРА]',
  '- Корень: { name, nodes, connections, settings: {executionOrder:"v1"} }',
  '- Нода: { id (уникальный), name (УНИКАЛЬНОЕ), type, typeVersion, position:[x,y], parameters }',
  '- Первая нода = триггер. Все ноды соединены. Минимум 4 ноды.',
  '',
  '[CONNECTIONS]',
  '- КАЖДАЯ нода (кроме триггера и Sticky Note) должна быть целевой хотя бы в одном connection.',
  '- IF нода: main[0]=true, main[1]=false — РАЗНЫЕ целевые ноды.',
  '- Switch нода: main[0], main[1], ... — по одному массиву на каждый output.',
  '- Когда IF/Switch ветки должны сойтись — подключи ОБЕ ветки к ОДНОЙ следующей ноде через connections. НЕ делай отдельную Merge ноду с try/catch.',
  '',
  '[ПОСЛЕДОВАТЕЛЬНОСТЬ — КРИТИЧНО]',
  '- Публикация в несколько платформ = ПОСЛЕДОВАТЕЛЬНАЯ цепочка: API_1 → Restore → API_2 → Restore → Notify',
  '- ЗАПРЕЩЕНО: несколько параллельных веток к одной Notify ноде (она сработает несколько раз)',
  '- Параллельные ветки допустимы ТОЛЬКО если у каждой СВОЯ конечная нода',
  '',
  '[PARAMETERS — КРИТИЧНО]',
  '- HTTP Request: ВСЕГДА method, url.',
  '- Если POST с телом: sendBody:true, specifyBody:"json", jsonBody.',
  '- Если GET с параметрами: sendQueryParameters:true, queryParameters.parameters:[{name,value}].',
  '- HTTP Request options: { timeout:30000, response:{response:{neverError:true, responseFormat:"json"}} }',
  '- Для скачивания файлов: responseFormat:"file" вместо "json".',
  '- НИКОГДА не оставляй parameters: {} — всегда заполняй.',
  '- Авторизация OpenAI: sendHeaders:true + headerParameters с Authorization: Bearer.',
  '',
  '[TELEGRAM BOT — ОБЯЗАТЕЛЬНАЯ АРХИТЕКТУРА]',
  '- Если задача включает Telegram бота с командами и ответами → ОБЯЗАТЕЛЬНО используй паттерн:',
  '  Telegram Trigger → Router+Config (с $getWorkflowStaticData) → Switch (по action) → ветки',
  '- Конфиг (токены, ID) хранится в объекте cfg ВНУТРИ ноды Router+Config',
  '- НЕ используй $env для Telegram бот задач — всё в cfg объекте',
  '',
  '[КОНТЕКСТ] После КАЖДОГО HTTP Request добавь Code ноду для восстановления контекста.',
  '',
  '[ЗАПРЕЩЕНО]',
  '- n8n-nodes-base.executeCommand, n8n-nodes-base.function — не существуют',
  '- process.env в Code нодах — используй $env.ИМЯ или cfg объект',
  '- Пустые parameters: {} на нодах (кроме триггеров)',
  '- Поле credentials в нодах',
  '- Параллельные ветки с binary данными',
  '- try/catch для выбора между $("NodeA") и $("NodeB") — вместо этого подключи обе ветки к одной ноде',
  '',
  '[ЗАМЕНА] function → n8n-nodes-base.code (поле jsCode)',
  '',
  '[STICKY NOTE] Добавь n8n-nodes-base.stickyNote id:"sticky-1", position:[240,-300], color:3.',
  '  Content: 1) Что делает 2) Credentials/Конфиг 3) Что настроить 4) Команды бота 5) Ошибки.',
  '  НЕ добавлять в connections.',
  '',
  'Верни ТОЛЬКО JSON объект без обёрток.'
].join('\n');

return [{
  json: {
    businessTask: $input.first().json.businessTask,
    failedTemplates: JSON.stringify($input.first().json.failedTemplates || []),
    exampleWorkflow: JSON.stringify(example, null, 2),
    apiPatterns: apiPatterns,
    rules: rules
  }
}];

parameters.jsonBody:
={{ JSON.stringify({
  "model": "claude-sonnet-4-6",
  "max_tokens": 1000,
