parameters.jsCode:
const response = $input.first().json;
const ctx = $('Контекст3').first().json;

let plan = { nodeHints: [], apiSearchQueries: [] };

try {
  const content = response.content || [];
  let text = content.filter(b => b.type === 'text').map(b => b.text || '').join('');
  text = text.replace(/^```json\s*/i, '').replace(/\s*```$/, '').trim();
  const s = text.indexOf('{'), e = text.lastIndexOf('}');
  if (s >= 0 && e > s) text = text.substring(s, e + 1);
  const parsed = JSON.parse(text);
  plan.nodeHints = parsed.nodeHints || [];
  plan.apiSearchQueries = parsed.apiSearchQueries || [];
} catch(e) {
  const task = ctx.businessTask.toLowerCase();
  const kw = ['webhook','http','googlesheets','telegram','slack','email','openai','gemini','notion','stripe','airtable','discord','vk'];
  plan.nodeHints = kw.filter(k => task.includes(k));
  plan.apiSearchQueries = plan.nodeHints.slice(0, 3);
  if (!plan.nodeHints.length) plan.nodeHints = task.split(/[\s,]+/).filter(w => w.length > 3).slice(0, 5);
}

// Нормализация: максимум 2 слова на запрос (не обрезаем до 1 слова)
plan.apiSearchQueries = plan.apiSearchQueries.map(q => {
  const words = q.toLowerCase().split(/\s+/).slice(0, 2);
  return words.join(' ');
});

// Маппинг известных алиасов
const aliasMap = {
  'nano': 'gemini',
  'banana': 'gemini',
  'imagen': 'gemini',
  'gpt': 'openai',
  'chatgpt': 'openai',
  'sheets': 'googlesheets',
  'docs': 'googledocs',
  'вк': 'vk',
  'вконтакте': 'vk',
  'vkontakte': 'vk',
  'тг': 'telegram',
  'tg': 'telegram',
};
plan.apiSearchQueries = plan.apiSearchQueries.map(q => aliasMap[q] || q);

// Гарантируем что apiSearchQueries НЕ пустой
if (!plan.apiSearchQueries.length) {
  plan.apiSearchQueries = plan.nodeHints.slice(0, 3).map(h => h.split(' ')[0].toLowerCase());
}

// Убираем дубли
plan.apiSearchQueries = [...new Set(plan.apiSearchQueries)];

return [{
  json: {
    ...ctx,
    nodeSearchQuery: plan.nodeHints.join(' ').substring(0, 150),
    apiSearchQuery: plan.apiSearchQueries[0],
    apiSearchQueriesAll: plan.apiSearchQueries
  }
}];

const searchResult = $input.first().json;
const ctx = $('Extract Plan1').first().json;

let nodeTypes = [];
let searchSummary = '';

try {
  const content = searchResult?.result?.content;
  let text = '';
  if (Array.isArray(content)) text = content.map(c => c.text || '').join('\n');
  else if (typeof content === 'string') text = content;
  searchSummary = text.substring(0, 3000);
  const typeMatches = text.match(/"nodeType":\s*"([^"]+)"/g) || [];
  const uniqueTypes = new Set();
  for (const match of typeMatches) {
    const type = match.match(/"nodeType":\s*"([^"]+)"/)?.[1];
    if (type && !type.includes('Trigger') && !type.includes('stickyNote')) uniqueTypes.add(type);
  }
  nodeTypes = Array.from(uniqueTypes).slice(0, 4);
} catch(e) {
  searchSummary = 'Ошибка: ' + e.message;
}

return [{
  json: {
    ...ctx,
    searchSummary,
    nodeTypes
  }
}];

const mcpResult = $input.first().json;
const ctx = $('Парсинг нод1').first().json;

let nodeDoc = '';
try {
  const content = mcpResult?.result?.content;
  if (Array.isArray(content)) nodeDoc = content.map(c => c.text || '').join('\n');
  else if (typeof content === 'string') nodeDoc = content;
} catch(e) {}

const nodeType = (ctx.nodeTypes && ctx.nodeTypes[0]) || '';
let allDocs = ctx.searchSummary + '\n\n';
if (nodeDoc) allDocs += '--- ' + nodeType + ' ---\n' + nodeDoc.substring(0, 5000) + '\n\n';

return [{
  json: {
    ...ctx,
    allDocs,
    nextNodeType: (ctx.nodeTypes && ctx.nodeTypes[1]) || ''
  }
}];

const mcpResult = $input.first().json;
const ctx = $('Save Node 1 Doc1').first().json;

let nodeDoc = '';
try {
  const content = mcpResult?.result?.content;
  if (Array.isArray(content)) nodeDoc = content.map(c => c.text || '').join('\n');
  else if (typeof content === 'string') nodeDoc = content;
} catch(e) {}

let allDocs = ctx.allDocs || '';
const nodeType = ctx.nextNodeType || '';
if (nodeDoc && nodeType) allDocs += '--- ' + nodeType + ' ---\n' + nodeDoc.substring(0, 5000) + '\n\n';

const remaining = (ctx.nodeTypes || []).slice(2);
if (remaining.length > 0) allDocs += '--- Дополнительные ноды ---\n' + remaining.join(', ') + '\n\n';

return [{
