    ...ctx,
    nodesDocs: allDocs.substring(0, 20000)
  }
}];

const raw = $input.first().json;
const ctx = $('Собрать Node Docs1').first().json;

let mcpData = null;
const rawText = typeof raw === 'string' ? raw : (raw.data || raw.body || JSON.stringify(raw));

if (typeof raw === 'object' && raw.result) mcpData = raw;
else {
  const lines = String(rawText).split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('data: ')) { try { mcpData = JSON.parse(trimmed.substring(6)); break; } catch(e) {} }
  }
  if (!mcpData) { try { mcpData = JSON.parse(String(rawText)); } catch(e) {} }
}

let searchText = '';
if (mcpData?.result?.content) {
  const content = mcpData.result.content;
  if (Array.isArray(content)) searchText = content.map(c => c.text || '').join('\n');
  else if (typeof content === 'string') searchText = content;
}

const matches = [...searchText.matchAll(/\*\*([^*]+)\*\*\s*\[/g)];
const candidates = matches.map(m => m[1]?.trim()).filter(Boolean);

return [{
  json: {
    ...ctx,
    apiSearchText: searchText.substring(0, 2000),
    apiServiceFound: candidates[0] || ''
  }
}];

const response = $input.first().json;

if (response.error) {
  return [{ json: { text: '', error: response.error, businessTask: $('Execute Sub-workflow Trigger').first().json.businessTask }}];
}

const content = response.content || [];
let text = content.filter(b => b.type === 'text').map(b => b.text || '').join('');

if (!text || text.trim() === '') {
  return [{ json: { text: '', error: { message: 'Claude вернул пустой ответ' }, businessTask: $('Execute Sub-workflow Trigger').first().json.businessTask }}];
}

text = text.replace(/^```json\s*/i, '').replace(/\s*```$/, '').trim();
const firstBrace = text.indexOf('{');
const lastBrace = text.lastIndexOf('}');
if (firstBrace > 0 && lastBrace > firstBrace) text = text.substring(firstBrace, lastBrace + 1);

try {
  const parsed = JSON.parse(text);
  if ((parsed.nodes?.length || 0) <= 1) {
    return [{ json: { text: '', error: { message: 'Слишком мало нод: ' + (parsed.nodes?.length || 0) }, businessTask: $('Execute Sub-workflow Trigger').first().json.businessTask }}];
  }
} catch(e) {}

return [{ json: { text, businessTask: $('Execute Sub-workflow Trigger').first().json.businessTask } }];

const raw = $input.first().json.text || '';
let wf;

try {
  let clean = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const s = clean.indexOf('{'), e = clean.lastIndexOf('}');
  if (s >= 0 && e > s) clean = clean.substring(s, e + 1);
  wf = JSON.parse(clean);
} catch (e) {
  return [{ json: { valid: false, errors: ['JSON parse: ' + e.message], workflow: null } }];
}

const errors = [];

// ═══════════════════════════════════════
// СТРУКТУРНЫЕ ПРОВЕРКИ (существующие)
// ═══════════════════════════════════════

if (!wf.name) errors.push('Нет name');
if (!Array.isArray(wf.nodes) || !wf.nodes.length) errors.push('Нет nodes');
if (!wf.connections) errors.push('Нет connections');

const names = new Set();
(wf.nodes || []).forEach((n, i) => {
  if (!n.name) n.name = 'Node' + i;
  if (!n.type) errors.push(n.name + ': нет type');
  if (!n.id) n.id = 'n-' + i;
  if (!n.typeVersion) n.typeVersion = 1;
  if (!n.parameters) n.parameters = {};
  if (!n.position) n.position = [250 + i * 200, 300];
  if (names.has(n.name)) errors.push('Дубль: ' + n.name);
  names.add(n.name);

  // Пустые parameters на не-триггерах
  if (n.type && !n.type.includes('Trigger') && !n.type.includes('stickyNote') && !n.type.includes('webhook')) {
    if (!n.parameters || Object.keys(n.parameters).length === 0) errors.push(n.name + ': пустые parameters');
  }

  // HTTP Request проверки
  if (n.type === 'n8n-nodes-base.httpRequest') {
    if (!n.parameters.url) errors.push(n.name + ': HTTP без url');
    if (!n.parameters.method) errors.push(n.name + ': HTTP без method');
  }

  // Code нода без jsCode
  if (n.type === 'n8n-nodes-base.code' && !n.parameters.jsCode) errors.push(n.name + ': Code без jsCode');
});

// Проверка connections — source существует
if (wf.connections) {
  Object.entries(wf.connections).forEach(([src, conn]) => {
    if (!names.has(src)) errors.push('Connection от: ' + src + ' (не существует)');
    (conn.main || []).forEach(outs => (outs || []).forEach(l => {
      if (!names.has(l.node)) errors.push('Connection к: ' + l.node + ' (не существует)');
    }));
  });
}

// Висящие ноды
const targetNodes = new Set();
Object.values(wf.connections || {}).forEach(conn => {
  (conn.main || []).forEach(outs => (outs || []).forEach(l => targetNodes.add(l.node)));
});
(wf.nodes || []).forEach(n => {
  if (!n.type.toLowerCase().includes('trigger') && !n.type.includes('webhook') && !n.type.includes('stickyNote') && !targetNodes.has(n.name))
    errors.push(n.name + ': висящая нода (не подключена как target ни в одном connection)');
});

// Нет триггера
if (!wf.nodes?.some(n => n.type.toLowerCase().includes('trigger') || n.type.includes('webhook')))
  errors.push('Нет триггера');

// ═══════════════════════════════════════
// ЛОГИЧЕСКИЕ ПРОВЕРКИ (НОВЫЕ)
// ═══════════════════════════════════════

const allJsCode = (wf.nodes || [])
  .filter(n => n.type === 'n8n-nodes-base.code')
  .map(n => n.parameters?.jsCode || '')
  .join('\n');
const allJson = JSON.stringify(wf.nodes || []);

// 1. Telegram бот без управления состоянием
const hasTgTrigger = (wf.nodes || []).some(n => n.type?.includes('telegramTrigger'));
const hasStaticData = allJsCode.includes('getWorkflowStaticData');
const taskLower = ($('Execute Sub-workflow Trigger').first().json.businessTask || '').toLowerCase();
const taskNeedsDialog = taskLower.includes('выложи') || taskLower.includes('команд') ||
  (taskLower.includes('бот') && (taskLower.includes('текст') || taskLower.includes('фото') || taskLower.includes('сторис') || taskLower.includes('пост')));

if (hasTgTrigger && taskNeedsDialog && !hasStaticData) {
  errors.push('КРИТИЧНО: Telegram бот с двухшаговым диалогом без $getWorkflowStaticData — бот не будет различать команду и ответ пользователя');
}

// 2. process.env в Code нодах
(wf.nodes || []).forEach(n => {
  if (n.type === 'n8n-nodes-base.code' && n.parameters?.jsCode?.includes('process.env')) {
    errors.push(n.name + ': используй $env вместо process.env (process.env недоступен в n8n Code нодах)');
  }
});

// 3. VK через POST+JSON body вместо GET+query
(wf.nodes || []).forEach(n => {
  const url = n.parameters?.url || '';
  const method = n.parameters?.method || '';
  const hasJsonBody = n.parameters?.specifyBody === 'json';
  if (url.includes('api.vk.com/method/') && method === 'POST' && hasJsonBody) {
    if (!url.includes('pu.vk.com') && !url.includes('Upload')) {
      errors.push(n.name + ': VK API метод не должен использовать POST+JSON body. Используй GET с queryParameters');
    }
  }
});

// 4. VK wall.post без обязательных параметров
(wf.nodes || []).forEach(n => {
  const url = n.parameters?.url || '';
  if (url.includes('wall.post')) {
    const nodeStr = JSON.stringify(n.parameters || {});
    if (!nodeStr.includes('owner_id')) errors.push(n.name + ': wall.post без owner_id');
    if (!nodeStr.includes('access_token')) errors.push(n.name + ': wall.post без access_token');
  }
});

// 5. HTTP Request без neverError
(wf.nodes || []).forEach(n => {
  if (n.type === 'n8n-nodes-base.httpRequest') {
    const opts = n.parameters?.options?.response?.response;
    if (!opts?.neverError) {
      errors.push(n.name + ': HTTP Request без neverError:true — workflow упадёт при ошибке API');
    }
  }
});

// 6. Switch с expression mode но без numberOutputs
(wf.nodes || []).forEach(n => {
  if (n.type === 'n8n-nodes-base.switch' && n.parameters?.mode === 'expression') {
    if (!n.parameters.numberOutputs) {
      errors.push(n.name + ': Switch с mode=expression без numberOutputs');
    }
  }
});

// 7. Параллельные ветки к одной ноде-уведомлению (дублирование)
const incomingConnectionCounts = {};
Object.values(wf.connections || {}).forEach(conn => {
  (conn.main || []).forEach(outs => (outs || []).forEach(l => {
    incomingConnectionCounts[l.node] = (incomingConnectionCounts[l.node] || 0) + 1;
  }));
});

// Считаем сколько РАЗНЫХ source-нод ведут к каждой ноде
const incomingSourceNodes = {};
Object.entries(wf.connections || {}).forEach(([src, conn]) => {
  (conn.main || []).forEach(outs => (outs || []).forEach(l => {
    if (!incomingSourceNodes[l.node]) incomingSourceNodes[l.node] = new Set();
    incomingSourceNodes[l.node].add(src);
  }));
});

Object.entries(incomingSourceNodes).forEach(([nodeName, sources]) => {
  if (sources.size > 1) {
    const node = (wf.nodes || []).find(n => n.name === nodeName);
    if (node && node.type === 'n8n-nodes-base.httpRequest') {
      const url = node.parameters?.url || '';
      const isTgSendMessage = url.includes('sendMessage');
      const isNotify = nodeName.toLowerCase().includes('notify') || nodeName.toLowerCase().includes('done');

      if (isTgSendMessage && isNotify) {
        // Проверяем: это IF/Switch merge (ок) или параллельные API-ветки (плохо)?
        // Если оба source — это Restore/Code ноды после РАЗНЫХ HTTP Request — это параллельные ветки
        const sourceArr = Array.from(sources);
        const sourceNodes = sourceArr.map(s => (wf.nodes || []).find(n => n.name === s));
        const allSourcesAreRestoreAfterHttp = sourceNodes.every(sn => {
          if (!sn || sn.type !== 'n8n-nodes-base.code') return false;
          // Проверяем что это Restore нода после HTTP (имя содержит restore/after)
          const name = (sn.name || '').toLowerCase();
          return name.includes('restore') || name.includes('after');
        });

        if (allSourcesAreRestoreAfterHttp && sources.size >= 2) {
          errors.push(nodeName + ': получает данные из ' + sources.size + ' параллельных Restore-нод — уведомление отправится ' + sources.size + ' раза. Сделай ПОСЛЕДОВАТЕЛЬНУЮ цепочку: API_1 → Restore → API_2 → Restore → Notify');
        }
      }
    }
  }
});

// 8. try/catch для выбора между $() нодами в Code
(wf.nodes || []).forEach(n => {
  if (n.type === 'n8n-nodes-base.code' && n.parameters?.jsCode) {
    const code = n.parameters.jsCode;
    if (code.includes('try') && code.includes('catch')) {
      // Находим все ссылки $('NodeName')
      const refs = code.match(/\$\(['"][^'"]+['"]\)/g) || [];
      const uniqueRefs = new Set(refs);
      if (uniqueRefs.size >= 2 && code.includes('catch')) {
        // Проверяем паттерн: try { x = $('A') } catch { x = $('B') }
        const hasFallbackPattern = code.includes('catch') &&
          refs.length >= 2 &&
          (code.includes('if (!ctx)') || code.includes('= $(' ));
        if (hasFallbackPattern) {
          errors.push(n.name + ': использует try/catch для выбора между нодами (' + Array.from(uniqueRefs).join(', ') + ') — это ненадёжно. Подключи обе ветки к следующей ноде через connections, n8n сам возьмёт данные из сработавшей ветки');
        }
      }
    }
  }
});

// ═══════════════════════════════════════
// АВТОМАТИЧЕСКИЕ ИСПРАВЛЕНИЯ
// ═══════════════════════════════════════

// Убираем credentials
wf.nodes?.forEach(n => { delete n.credentials; });

// Ставим settings
wf.settings = { executionOrder: 'v1' };

// Определяем серьёзность ошибок
const serious = errors.filter(e =>
  !e.includes('Дубль')
);

return [{
  json: {
    valid: serious.length === 0,
    errors,
    workflow: wf,
    businessTask: $('Execute Sub-workflow Trigger').first().json.businessTask
  }
}];

const wf = $('Валидация2').first().json.workflow;
return [{ json: {
  success: true,
  workflowJson: wf,
  workflowName: wf.name,
  businessTask: $('Execute Sub-workflow Trigger').first().json.businessTask,
  summary: 'Воркфлоу сгенерирован и прошёл валидацию API'
} }];

const response = $input.all()[0].json;
let errorDetail = response.message || (typeof response.error === 'string' ? response.error : JSON.stringify(response.error || response).substring(0, 500));
return [{ json: {
  success: false,
  error: 'API rejected: ' + errorDetail,
  workflowJson: $('Валидация2').first().json.workflow,
  businessTask: $('Execute Sub-workflow Trigger').first().json.businessTask,
  summary: 'n8n API не принял: ' + errorDetail
} }];

