parameters.jsCode:
const item = $input.first().json;
const wf = item.workflow;
const fixes = [];

if (!wf || !wf.nodes) {
  return [{ json: item }];
}

// ═══════════════════════════════════════
// FIX 1: Добавить neverError ко всем HTTP Request
// ═══════════════════════════════════════
wf.nodes.forEach(n => {
  if (n.type === 'n8n-nodes-base.httpRequest') {
    if (!n.parameters.options) n.parameters.options = {};
    if (!n.parameters.options.response) n.parameters.options.response = {};
    if (!n.parameters.options.response.response) n.parameters.options.response.response = {};

    if (!n.parameters.options.response.response.neverError) {
      n.parameters.options.response.response.neverError = true;
      fixes.push(n.name + ': добавлен neverError:true');
    }

    if (!n.parameters.options.response.response.responseFormat) {
      // Определяем формат по контексту
      const url = n.parameters.url || '';
      if (url.includes('/file/bot') || n.parameters.options?.response?.response?.responseFormat === 'file') {
        n.parameters.options.response.response.responseFormat = 'file';
      } else {
        n.parameters.options.response.response.responseFormat = 'json';
      }
      fixes.push(n.name + ': добавлен responseFormat');
    }

    // Добавить timeout если нет
    if (!n.parameters.options.timeout) {
      n.parameters.options.timeout = 30000;
      fixes.push(n.name + ': добавлен timeout:30000');
    }
  }
});

// ═══════════════════════════════════════
// FIX 2: Убрать credentials (n8n API не принимает)
// ═══════════════════════════════════════
wf.nodes.forEach(n => {
  if (n.credentials) {
    delete n.credentials;
    fixes.push(n.name + ': удалён credentials');
  }
});

// ═══════════════════════════════════════
// FIX 3: settings.executionOrder = 'v1'
// ═══════════════════════════════════════
if (!wf.settings || wf.settings.executionOrder !== 'v1') {
  wf.settings = { executionOrder: 'v1' };
  fixes.push('settings: установлен executionOrder:v1');
}

// ═══════════════════════════════════════
// FIX 4: Исправить позиции если совпадают
// ═══════════════════════════════════════
const positionMap = new Map();
wf.nodes.forEach(n => {
  if (!n.position) n.position = [250, 300];
  const key = n.position[0] + ',' + n.position[1];
  if (positionMap.has(key)) {
    n.position = [n.position[0], n.position[1] + 200];
    fixes.push(n.name + ': сдвинута позиция (совпадала с ' + positionMap.get(key) + ')');
  }
  positionMap.set(n.position[0] + ',' + n.position[1], n.name);
});

// ═══════════════════════════════════════
// FIX 5: Добавить typeVersion если нет
// ═══════════════════════════════════════
wf.nodes.forEach(n => {
  if (!n.typeVersion) {
    if (n.type === 'n8n-nodes-base.httpRequest') n.typeVersion = 4.2;
    else if (n.type === 'n8n-nodes-base.code') n.typeVersion = 2;
    else if (n.type === 'n8n-nodes-base.telegramTrigger') n.typeVersion = 1.1;
    else if (n.type === 'n8n-nodes-base.switch') n.typeVersion = 3.2;
    else if (n.type === 'n8n-nodes-base.if') n.typeVersion = 2.1;
    else if (n.type === 'n8n-nodes-base.set') n.typeVersion = 3.4;
    else if (n.type === 'n8n-nodes-base.stickyNote') n.typeVersion = 1;
