if (ctx.failedTemplates && JSON.stringify(ctx.failedTemplates) !== '[]') {
  userParts.push("\nЭти шаблоны НЕ подошли, не повторяй:");
  userParts.push(JSON.stringify(ctx.failedTemplates).substring(0, 3000));
}

const userMsg = userParts.join("\n");

const requestBody = {
  model: "claude-sonnet-4-6",
  max_tokens: 25000,
  system: fullSystem,
  messages: [{ role: "user", content: userMsg }]
};

return [{ json: {
  ...ctx,
  anthropicRequestBody: JSON.stringify(requestBody)
}}];

const response = $input.first().json;

if (response.error) {
  return [{ json: { text: '', error: response.error, businessTask: $('Trigger').first().json.businessTask, plan: $('Extract Plan').first().json.plan }}];
}

const content = response.content || [];
let text = content.filter(b => b.type === 'text').map(b => b.text || '').join('');

if (!text?.trim()) {
  return [{ json: { text: '', error: { message: 'Claude returned empty response' }, businessTask: $('Trigger').first().json.businessTask, plan: $('Extract Plan').first().json.plan }}];
}

text = text.replace(/^\`\`\`json\s*/i, '').replace(/\s*\`\`\`$/, '').trim();
const firstBrace = text.indexOf('{');
const lastBrace = text.lastIndexOf('}');
if (firstBrace > 0 && lastBrace > firstBrace) text = text.substring(firstBrace, lastBrace + 1);

try {
  const parsed = JSON.parse(text);
  if ((parsed.nodes?.length || 0) <= 1) {
    return [{ json: { text: '', error: { message: 'Too few nodes: ' + (parsed.nodes?.length || 0) }, businessTask: $('Trigger').first().json.businessTask, plan: $('Extract Plan').first().json.plan }}];
  }
} catch(e) {}

return [{ json: {
  text,
  businessTask: $('Trigger').first().json.businessTask,
  plan: $('Extract Plan').first().json.plan,
  planText: $('Extract Plan').first().json.planText,
  ragTemplates: $('Extract Plan').first().json.ragTemplates,
  nodesDocs: $('Extract Plan').first().json.nodesDocs,
  apiDocs: $('Extract Plan').first().json.apiDocs,
  complexity: $('Extract Plan').first().json.complexity
}}];

const raw = $input.first().json.text || '';
let wf;

try {
  let clean = raw.replace(/\`\`\`json\n?/g, '').replace(/\n?\`\`\`/g, '').trim();
  const s = clean.indexOf('{'), e = clean.lastIndexOf('}');
  if (s >= 0 && e > s) clean = clean.substring(s, e + 1);
  wf = JSON.parse(clean);
} catch (e) {
  return [{ json: { valid: false, errors: ['JSON parse: ' + e.message], workflow: null, businessTask: $json.businessTask, plan: $json.plan, planText: $json.planText, ragTemplates: $json.ragTemplates, nodesDocs: $json.nodesDocs, apiDocs: $json.apiDocs, complexity: $json.complexity } }];
}

const errors = [];

// ═══ LAYER 1: SCHEMA COMPLIANCE ═══
if (!wf.name) wf.name = 'Generated Workflow';
if (!Array.isArray(wf.nodes) || !wf.nodes.length) errors.push('[SCHEMA] No nodes array');
if (!wf.connections) errors.push('[SCHEMA] No connections');

const names = new Set();
(wf.nodes || []).forEach((n, i) => {
  if (!n.name) n.name = 'Node' + i;
  if (!n.type) errors.push('[SCHEMA] ' + n.name + ': no type');
  if (!n.id) n.id = 'n-' + i + '-' + Date.now().toString(36);
  if (!n.typeVersion) n.typeVersion = 1;
  if (!n.parameters) n.parameters = {};
  if (!n.position) n.position = [250 + i * 220, 300];
  if (names.has(n.name)) errors.push('[SCHEMA] Duplicate name: ' + n.name);
  names.add(n.name);
});

// ═══ LAYER 2: NODE TYPE VALIDATION ═══
const knownNodePrefixes = ['n8n-nodes-base.', 'n8n-nodes-langchain.', '@n8n/'];
(wf.nodes || []).forEach(n => {
  if (n.type && !knownNodePrefixes.some(p => n.type.startsWith(p))) {
    errors.push('[TYPE] ' + n.name + ': unknown node type prefix: ' + n.type);
  }
  // Check for non-existent node types
  const banned = ['n8n-nodes-base.function', 'n8n-nodes-base.executeCommand', 'n8n-nodes-base.merge'];
  if (banned.includes(n.type)) {
    errors.push('[TYPE] ' + n.name + ': banned/deprecated type ' + n.type + '. Use n8n-nodes-base.code instead of function');
  }
});

// ═══ LAYER 3: CONNECTION INTEGRITY ═══
if (wf.connections) {
  Object.entries(wf.connections).forEach(([src, conn]) => {
    if (!names.has(src)) errors.push('[CONN] Source not found: ' + src);
    (conn.main || []).forEach((outs, outIdx) => (outs || []).forEach(l => {
      if (!names.has(l.node)) errors.push('[CONN] Target not found: ' + l.node + ' (from ' + src + ')');
    }));
  });
}

// Check for orphan nodes (not connected as target)
const targetNodes = new Set();
Object.values(wf.connections || {}).forEach(conn => {
  (conn.main || []).forEach(outs => (outs || []).forEach(l => targetNodes.add(l.node)));
});
(wf.nodes || []).forEach(n => {
  if (!n.type?.toLowerCase().includes('trigger') && !n.type?.includes('webhook') && !n.type?.includes('stickyNote') && !targetNodes.has(n.name))
    errors.push('[CONN] Orphan node (no incoming connection): ' + n.name);
});

// Check for circular connections (simple check: node connects to itself)
Object.entries(wf.connections || {}).forEach(([src, conn]) => {
  (conn.main || []).forEach(outs => (outs || []).forEach(l => {
    if (l.node === src) errors.push('[CONN] Self-loop: ' + src);
  }));
});

// ═══ LAYER 4: DAG VALIDATION ═══
if (!wf.nodes?.some(n => n.type?.toLowerCase().includes('trigger') || n.type?.includes('webhook')))
  errors.push('[DAG] No trigger node');

// ═══ LAYER 5: PARAMETER COMPLETENESS ═══
(wf.nodes || []).forEach(n => {
  // Empty parameters on non-trivial nodes
  if (n.type && !n.type.includes('Trigger') && !n.type.includes('stickyNote') && !n.type.includes('webhook')) {
    if (!n.parameters || Object.keys(n.parameters).length === 0) errors.push('[PARAMS] ' + n.name + ': empty parameters');
  }
  // HTTP Request checks
  if (n.type === 'n8n-nodes-base.httpRequest') {
    if (!n.parameters.url) errors.push('[PARAMS] ' + n.name + ': HTTP without url');
    if (!n.parameters.method) errors.push('[PARAMS] ' + n.name + ': HTTP without method');
    // neverError check
    const opts = n.parameters?.options?.response?.response;
    if (!opts?.neverError) errors.push('[PARAMS] ' + n.name + ': HTTP without neverError:true');
  }
  // Code without jsCode
  if (n.type === 'n8n-nodes-base.code' && !n.parameters.jsCode) errors.push('[PARAMS] ' + n.name + ': Code without jsCode');
  // Switch without numberOutputs
  if (n.type === 'n8n-nodes-base.switch' && n.parameters?.mode === 'expression' && !n.parameters.numberOutputs)
    errors.push('[PARAMS] ' + n.name + ': Switch expression without numberOutputs');
});

// ═══ LAYER 6: LOGIC CHECKS ═══
const allJsCode = (wf.nodes || []).filter(n => n.type === 'n8n-nodes-base.code').map(n => n.parameters?.jsCode || '').join('\n');
const taskLower = ($json.businessTask || '').toLowerCase();

// 6a. Telegram bot without staticData
const hasTgTrigger = (wf.nodes || []).some(n => n.type?.includes('telegramTrigger'));
const hasStaticData = allJsCode.includes('getWorkflowStaticData');
const taskNeedsDialog = taskLower.includes('выложи') || taskLower.includes('команд') ||
  (taskLower.includes('бот') && (taskLower.includes('текст') || taskLower.includes('фото') || taskLower.includes('сторис') || taskLower.includes('пост')));
if (hasTgTrigger && taskNeedsDialog && !hasStaticData)
  errors.push('[LOGIC] Telegram bot with dialog but no $getWorkflowStaticData');

// 6b. process.env in Code
(wf.nodes || []).forEach(n => {
  if (n.type === 'n8n-nodes-base.code' && n.parameters?.jsCode?.includes('process.env'))
    errors.push('[LOGIC] ' + n.name + ': process.env not available, use $env or cfg');
});

// 6c. VK via POST+JSON
(wf.nodes || []).forEach(n => {
  const url = n.parameters?.url || '';
  if (url.includes('api.vk.com/method/') && n.parameters?.method === 'POST' && n.parameters?.specifyBody === 'json' && !url.includes('pu.vk.com'))
    errors.push('[LOGIC] ' + n.name + ': VK API must use GET+queryParams, not POST+JSON');
});

// 6d. Parallel branches to single Notify
const incomingSources = {};
Object.entries(wf.connections || {}).forEach(([src, conn]) => {
  (conn.main || []).forEach(outs => (outs || []).forEach(l => {
    if (!incomingSources[l.node]) incomingSources[l.node] = new Set();
    incomingSources[l.node].add(src);
  }));
});
Object.entries(incomingSources).forEach(([nodeName, sources]) => {
  if (sources.size > 1) {
    const node = (wf.nodes || []).find(n => n.name === nodeName);
    if (node?.type === 'n8n-nodes-base.httpRequest') {
      const url = node.parameters?.url || '';
      const isNotify = url.includes('sendMessage') && (nodeName.toLowerCase().includes('notify') || nodeName.toLowerCase().includes('done') || nodeName.toLowerCase().includes('отчёт'));
      if (isNotify) {
        const sourceArr = Array.from(sources);
        const sourceNodes = sourceArr.map(s => (wf.nodes || []).find(n => n.name === s));
        const allRestore = sourceNodes.every(sn => sn?.type === 'n8n-nodes-base.code' && (sn.name.toLowerCase().includes('restore') || sn.name.toLowerCase().includes('after')));
        if (allRestore && sources.size >= 2)
          errors.push('[LOGIC] ' + nodeName + ': ' + sources.size + ' parallel Restore nodes → notification fires ' + sources.size + ' times. Use SEQUENTIAL chain');
      }
    }
  }
});

// 6e. try/catch for $() node references
(wf.nodes || []).forEach(n => {
  if (n.type === 'n8n-nodes-base.code' && n.parameters?.jsCode) {
    const code = n.parameters.jsCode;
    if (code.includes('try') && code.includes('catch')) {
      const refs = code.match(/\$\(['"][^'"]+['"]\)/g) || [];
      if (new Set(refs).size >= 2 && code.includes('.first()'))
        errors.push('[LOGIC] ' + n.name + ': try/catch between $() refs is unreliable. Connect both branches to same target node instead');
    }
  }
});

// 6f. Expression without = prefix (check jsonBody and url fields)
(wf.nodes || []).forEach(n => {
  if (n.type === 'n8n-nodes-base.httpRequest') {
    const url = n.parameters?.url || '';
    const jsonBody = n.parameters?.jsonBody || '';
    if (url.includes('{{') && !url.startsWith('='))
      errors.push('[LOGIC] ' + n.name + ': url with {{ }} must start with = prefix');
    if (jsonBody.includes('{{') && !jsonBody.startsWith('='))
      errors.push('[LOGIC] ' + n.name + ': jsonBody with {{ }} must start with = prefix');
  }
});

// Classify severity
const critical = errors.filter(e => e.includes('[SCHEMA]') || e.includes('[CONN]') || e.includes('[DAG]') || e.includes('[LOGIC]'));
const warnings = errors.filter(e => e.includes('[PARAMS]') || e.includes('[TYPE]'));

// Auto-set settings
wf.settings = { executionOrder: 'v1' };

return [{ json: {
  valid: critical.length === 0,
  errors,
  errorCount: { critical: critical.length, warnings: warnings.length, total: errors.length },
  workflow: wf,
  businessTask: $json.businessTask,
  plan: $json.plan,
  planText: $json.planText,
  ragTemplates: $json.ragTemplates,
  nodesDocs: $json.nodesDocs,
  apiDocs: $json.apiDocs,
  complexity: $json.complexity
}}];

const wf = $('Validate').first().json.workflow;
const plan = $('Extract Plan').first().json.plan;
return [{ json: {
  success: true,
  workflowJson: wf,
  workflowName: wf.name,
  businessTask: $('Trigger').first().json.businessTask,
  plan: plan,
  summary: 'Воркфлоу сгенерирован, прошёл валидацию и принят n8n API'
}}];

const response = $input.all()[0].json;
let errorDetail = response.message || (typeof response.error === 'string' ? response.error : JSON.stringify(response.error || response).substring(0, 500));
return [{ json: {
  success: false,
  error: 'n8n API rejected: ' + errorDetail,
  workflowJson: $('Validate').first().json.workflow,
  businessTask: $('Trigger').first().json.businessTask,
  summary: 'Воркфлоу прошёл валидацию но n8n API не принял: ' + errorDetail
}}];

const retryCount = $json.retryCount || 1;
// Retry 1-2: Sonnet repairs. Retry 3+: Opus regeneration from scratch
const useOpus = retryCount >= 3;
const model = useOpus ? 'claude-opus-4-6' : 'claude-sonnet-4-6';

return [{ json: {
  ...$json,
  repairModel: model,
  isRegeneration: useOpus
}}];

const data = $input.first().json;
const isRegen = data.isRegeneration;

let prompt;
if (isRegen) {
  prompt = "Предыдущая попытка генерации провалилась с ошибками:\n" + JSON.stringify(data.errors) + "\n\nОригинальный план:\n" + (data.planText || '') + "\n\nЗадача: " + data.businessTask + "\n\nСгенерируй воркфлоу ЗАНОВО с нуля, избегая перечисленных ошибок.\nВерни ТОЛЬКО JSON без обёрток.";
} else {
  prompt = "В JSON воркфлоу найдены ошибки:\n" + JSON.stringify(data.errors) + "\n\nВот JSON:\n" + JSON.stringify(data.workflow) + "\n\nИсправь ВСЕ ошибки и верни ТОЛЬКО исправленный JSON без обёрток.";
}

const requestBody = {
  model: data.repairModel,
  max_tokens: 30000,
  messages: [{ role: "user", content: prompt }]
};

return [{ json: { ...data, anthropicRepairBody: JSON.stringify(requestBody) } }];

const data = $input.first().json;
return [{ json: {
  success: false,
  error: 'Validation failed after ' + (data.retryCount || 0) + ' repair attempts',
  errors: data.errors || [],
  workflowJson: data.workflow,
  businessTask: data.businessTask,
  summary: 'Воркфлоу не прошёл валидацию после макс. попыток ремонта. JSON прилагается для ручной доработки.'
}}];

const item = $input.first().json;
const wf = item.workflow;
const fixes = [];

if (!wf || !wf.nodes) return [{ json: item }];

// FIX 1: neverError + responseFormat + timeout on all HTTP
wf.nodes.forEach(n => {
  if (n.type === 'n8n-nodes-base.httpRequest') {
    if (!n.parameters.options) n.parameters.options = {};
    if (!n.parameters.options.response) n.parameters.options.response = {};
    if (!n.parameters.options.response.response) n.parameters.options.response.response = {};
    if (!n.parameters.options.response.response.neverError) {
      n.parameters.options.response.response.neverError = true;
      fixes.push(n.name + ': +neverError');
    }
    if (!n.parameters.options.response.response.responseFormat) {
      const url = n.parameters.url || '';
      n.parameters.options.response.response.responseFormat = url.includes('/file/bot') ? 'file' : 'json';
      fixes.push(n.name + ': +responseFormat');
    }
    if (!n.parameters.options.timeout) {
      n.parameters.options.timeout = 30000;
      fixes.push(n.name + ': +timeout');
    }
  }
});

// FIX 2: Remove credentials
wf.nodes.forEach(n => { if (n.credentials) { delete n.credentials; fixes.push(n.name + ': -credentials'); } });

// FIX 3: settings
wf.settings = { executionOrder: 'v1' };

// FIX 4: Fix overlapping positions
const posMap = new Map();
wf.nodes.forEach(n => {
  if (!n.position) n.position = [250, 300];
  const key = n.position[0] + ',' + n.position[1];
  if (posMap.has(key)) { n.position = [n.position[0], n.position[1] + 200]; fixes.push(n.name + ': shifted position'); }
  posMap.set(n.position[0] + ',' + n.position[1], n.name);
});

// FIX 5: typeVersion defaults
const tvDefaults = { 'n8n-nodes-base.httpRequest': 4.2, 'n8n-nodes-base.code': 2, 'n8n-nodes-base.telegramTrigger': 1.1, 'n8n-nodes-base.switch': 3.2, 'n8n-nodes-base.if': 2.1, 'n8n-nodes-base.set': 3.4, 'n8n-nodes-base.stickyNote': 1, 'n8n-nodes-base.webhook': 2, 'n8n-nodes-base.scheduleTrigger': 1.2, 'n8n-nodes-base.googleSheets': 4.5 };
wf.nodes.forEach(n => {
  if (!n.typeVersion) { n.typeVersion = tvDefaults[n.type] || 1; fixes.push(n.name + ': +typeVersion'); }
});

// FIX 6: process.env → $env
wf.nodes.forEach(n => {
  if (n.type === 'n8n-nodes-base.code' && n.parameters?.jsCode?.includes('process.env.')) {
    n.parameters.jsCode = n.parameters.jsCode.replace(/process\.env\.(\w+)/g, '\$env.$1');
    fixes.push(n.name + ': process.env→$env');
  }
});

// FIX 7: function → code
wf.nodes.forEach(n => {
  if (n.type === 'n8n-nodes-base.function') {
    n.type = 'n8n-nodes-base.code'; n.typeVersion = 2;
    if (n.parameters.functionCode && !n.parameters.jsCode) { n.parameters.jsCode = n.parameters.functionCode; delete n.parameters.functionCode; }
    fixes.push(n.name + ': function→code');
  }
});

// FIX 8: Unique IDs
const usedIds = new Set();
wf.nodes.forEach((n, i) => {
  if (!n.id || usedIds.has(n.id)) { n.id = 'node-' + i + '-' + Date.now().toString(36); fixes.push(n.name + ': +uniqueId'); }
  usedIds.add(n.id);
});

// FIX 9: Expression = prefix
wf.nodes.forEach(n => {
  if (n.type === 'n8n-nodes-base.httpRequest') {
    ['url', 'jsonBody'].forEach(field => {
      if (n.parameters[field] && n.parameters[field].includes('{{') && !n.parameters[field].startsWith('=')) {
        n.parameters[field] = '=' + n.parameters[field];
        fixes.push(n.name + ': +expression prefix on ' + field);
      }
    });
  }
});

return [{ json: { ...item, workflow: wf, autoFixes: fixes } }];

const item = $input.first().json;
const wf = item.workflow;
const cleanWorkflow = {
  name: wf.name || 'Generated Workflow',
  nodes: (wf.nodes || []).map(({ credentials, ...n }) => n),
  connections: wf.connections || {},
  settings: wf.settings || { executionOrder: 'v1' }
};
return [{ json: { workflow: cleanWorkflow, businessTask: item.businessTask } }];

const response = $input.first().json;
const ctx = $('Choose Repair Model').first().json;

const content = response.content || [];
let text = content.filter(b => b.type === 'text').map(b => b.text || '').join('');
text = text.replace(/^\`\`\`json\s*/i, '').replace(/\s*\`\`\`$/, '').trim();
const s = text.indexOf('{'), e = text.lastIndexOf('}');
if (s >= 0 && e > s) text = text.substring(s, e + 1);

return [{ json: {
  text,
  businessTask: ctx.businessTask,
  plan: ctx.plan,
  planText: ctx.planText,
  ragTemplates: ctx.ragTemplates,
  nodesDocs: ctx.nodesDocs,
  apiDocs: ctx.apiDocs,
  complexity: ctx.complexity,
  retryCount: ctx.retryCount
}}];
